package br.com.admeclesial.application.dashboard;
import br.com.admeclesial.application.usuario.SegurancaOrganizacaoService; import br.com.admeclesial.infrastructure.persistence.relatorio.DashboardRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.time.*; import java.util.UUID;
@Service public class DashboardApplicationService { private final DashboardRepository repo; private final SegurancaOrganizacaoService seguranca; public DashboardApplicationService(DashboardRepository r,SegurancaOrganizacaoService s){repo=r;seguranca=s;}
 @Transactional(readOnly=true) public DashboardAdministradorResponse administrador(UUID org,LocalDate inicio,LocalDate fim){if(org==null)throw new IllegalArgumentException("Organização é obrigatória");if(inicio==null||fim==null){var hoje=LocalDate.now();inicio=hoje.withDayOfMonth(1);fim=hoje.withDayOfMonth(hoje.lengthOfMonth());}if(fim.isBefore(inicio))throw new IllegalArgumentException("Período final não pode ser anterior ao inicial");seguranca.validarAcesso(org);var o=repo.operacional(org,inicio,fim);var f=repo.financeiro(org,inicio,fim);var e=nvl(f.getEntradas());var s=nvl(f.getSaidas());return new DashboardAdministradorResponse(inicio,fim,n(o.getPessoasAtivas()),n(o.getTurmasAtivas()),n(o.getInscritosAtivos()),n(o.getProjetosExecucao()),n(o.getSacramentosPeriodo()),n(o.getTurmasSemCatequistaPrincipal()),e,s,e.subtract(s),n(f.getContribuicoes()),nvl(f.getValorContribuicoes()),n(f.getContasVencidas()),nvl(f.getSaldoContasVencidas()),n(f.getRepassesVencidos()),nvl(f.getSaldoRepassesVencidos()),n(f.getProjetosRecursoSemUso()));}
 @Transactional(readOnly=true) public DashboardConsultaResponse consulta(UUID org,LocalDate inicio,LocalDate fim){validar(org,inicio,fim);var d=repo.consulta(org,inicio,fim);return new DashboardConsultaResponse(inicio,fim,n(d.getPessoasAtivas()),n(d.getTurmasAtivas()),n(d.getInscritosAtivos()),n(d.getSacramentosPeriodo()),n(d.getProjetosExecucao()));}
 @Transactional(readOnly=true) public DashboardSecretariaResponse secretaria(UUID org,LocalDate inicio,LocalDate fim){validar(org,inicio,fim);var d=repo.secretaria(org,inicio,fim);return new DashboardSecretariaResponse(inicio,fim,n(d.getPessoasAtivas()),n(d.getNovosCadastros()),n(d.getSacramentosRegistrados()),n(d.getMatrimoniosRegistrados()),n(d.getTurmasAtivas()),n(d.getTurmasSemCatequistaPrincipal()));}
 @Transactional(readOnly=true) public DashboardCatequeseResponse catequese(UUID org,LocalDate inicio,LocalDate fim){validar(org,inicio,fim);var d=repo.catequese(org);return new DashboardCatequeseResponse(inicio,fim,n(d.getTurmasAtivas()),n(d.getInscritosAtivos()),n(d.getVagasDisponiveis()),n(d.getTurmasSemCatequistaPrincipal()),n(d.getTurmasSemVagas()));}
 @Transactional(readOnly=true) public DashboardFinanceiroResponse financeiro(UUID org,LocalDate inicio,LocalDate fim){validar(org,inicio,fim);var f=repo.financeiro(org,inicio,fim);var e=nvl(f.getEntradas());var s=nvl(f.getSaidas());var rv=nvl(f.getRecursosVinculados());var ru=nvl(f.getRecursosUtilizados());return new DashboardFinanceiroResponse(inicio,fim,e,s,e.subtract(s),n(f.getContribuicoes()),nvl(f.getValorContribuicoes()),n(f.getContasVencidas()),nvl(f.getSaldoContasVencidas()),n(f.getRepassesVencidos()),nvl(f.getSaldoRepassesVencidos()),n(f.getProjetosExecucao()),rv,ru,rv.subtract(ru),n(f.getProjetosRecursoSemUso()));}
 private void validar(UUID org,LocalDate inicio,LocalDate fim){if(org==null)throw new IllegalArgumentException("Organização é obrigatória");if(inicio==null||fim==null)throw new IllegalArgumentException("Período é obrigatório");if(fim.isBefore(inicio))throw new IllegalArgumentException("Período final não pode ser anterior ao inicial");seguranca.validarAcesso(org);}
 private long n(Long v){return v==null?0:v;} private BigDecimal nvl(BigDecimal v){return v==null?BigDecimal.ZERO:v;}
}
